create table public.chat_groups(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 100),creator uuid not null default auth.uid() references public.profiles(id));
create table public.chat_group_members(group_id uuid references public.chat_groups(id) on delete cascade,user_id uuid references public.profiles(id),primary key(group_id,user_id));
create table public.chat_group_messages(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.chat_groups(id),sender uuid not null default auth.uid() references public.profiles(id),body text not null check(length(trim(body)) between 1 and 4000),created_at timestamptz not null default now(),attachment text);
alter table public.internal_messages add column attachment text;
grant insert(attachment) on public.internal_messages to authenticated;
alter table public.chat_groups enable row level security;
alter table public.chat_group_members enable row level security;
alter table public.chat_group_messages enable row level security;
revoke all on public.chat_groups,public.chat_group_members,public.chat_group_messages from anon,authenticated;
grant select on public.chat_groups,public.chat_group_members,public.chat_group_messages to authenticated;
grant insert(name) on public.chat_groups to authenticated;
grant insert(group_id,user_id) on public.chat_group_members to authenticated;
grant insert(group_id,body,attachment) on public.chat_group_messages to authenticated;
create policy own_membership on public.chat_group_members for select to authenticated using(user_id=auth.uid());
create policy admin_membership on public.chat_group_members for insert to authenticated with check(public.is_admin());
create policy group_read on public.chat_groups for select to authenticated using(creator=auth.uid() or exists(select 1 from public.chat_group_members m where m.group_id=id and m.user_id=auth.uid()));
create policy group_create on public.chat_groups for insert to authenticated with check(public.is_admin() and creator=auth.uid());
create policy group_message_read on public.chat_group_messages for select to authenticated using(exists(select 1 from public.chat_group_members m where m.group_id=chat_group_messages.group_id and m.user_id=auth.uid()));
create policy group_message_send on public.chat_group_messages for insert to authenticated with check(sender=auth.uid() and exists(select 1 from public.chat_group_members m where m.group_id=chat_group_messages.group_id and m.user_id=auth.uid()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('chat-files','chat-files',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']);
create policy chat_upload on storage.objects for insert to authenticated with check(bucket_id='chat-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy chat_download on storage.objects for select to authenticated using(bucket_id='chat-files' and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.internal_messages m where m.attachment=storage.objects.name) or exists(select 1 from public.chat_group_messages m where m.attachment=storage.objects.name)));
alter publication supabase_realtime add table public.chat_group_messages;
